"use client";

/**
 * MEDBAY icon set.
 *
 * UI glyphs are thin wrappers over lucide-react (the shadcn icon library) so
 * the console keeps a consistent professional stroke style. Every export keeps
 * the MEDBAY name + `{ size, ...svgProps }` API used across the app.
 *
 * The three `Logo*Icon` wordmarks are static brand assets served from
 * `public/brand/` (generated by `scripts/gen-logo-assets.py` — Unbounded
 * glyphs baked to paths at the supplied design SVGs' coordinates). Each
 * renders a plain <img>, so they never depend on webfonts or CSS vars.
 */

import type { ComponentProps, ComponentType, SVGProps } from "react";
import {
  ArrowRight,
  BedDouble,
  Camera,
  CircleCheck,
  Cloud,
  Cpu,
  Database,
  Eye,
  Globe,
  HeartPulse,
  Images,
  LayoutGrid,
  List,
  Mic,
  OctagonAlert,
  PersonStanding,
  Search,
  Sparkles,
  Thermometer,
  TriangleAlert,
  Volume2,
  Wind,
  type LucideProps,
} from "lucide-react";

export type MedbayIconProps = SVGProps<SVGSVGElement> & { size?: number | string };

function wrap(C: ComponentType<LucideProps>, display: string) {
  function MedbayIcon({ size = 16, ...p }: MedbayIconProps) {
    return <C size={size} strokeWidth={1.75} {...(p as LucideProps)} />;
  }
  MedbayIcon.displayName = display;
  return MedbayIcon;
}

export const AllIcon = wrap(Images, "AllIcon");
export const ArrowIcon = wrap(ArrowRight, "ArrowIcon");
export const AstronautIcon = wrap(PersonStanding, "AstronautIcon");
export const BedIcon = wrap(BedDouble, "BedIcon");
export const CameraIcon = wrap(Camera, "CameraIcon");
export const CloudLlmIcon = wrap(Cloud, "CloudLlmIcon");
export const CriticalIcon = wrap(OctagonAlert, "CriticalIcon");
export const DatabaseIcon = wrap(Database, "DatabaseIcon");
export const LocalLlmIcon = wrap(Cpu, "LocalLlmIcon");
export const GridViewIcon = wrap(LayoutGrid, "GridViewIcon");
export const HealthyIcon = wrap(CircleCheck, "HealthyIcon");
export const HeartIcon = wrap(HeartPulse, "HeartIcon");
export const HistoryIcon = wrap(Globe, "HistoryIcon");
export const ListViewIcon = wrap(List, "ListViewIcon");
export const MicrophoneIcon = wrap(Mic, "MicrophoneIcon");
export const NewSkinIcon = wrap(Sparkles, "NewSkinIcon");
export const OxygenIcon = wrap(Wind, "OxygenIcon");
export const PredictionIcon = wrap(Eye, "PredictionIcon");
export const RiskIcon = wrap(TriangleAlert, "RiskIcon");
export const SearchIcon = wrap(Search, "SearchIcon");
export const TemperatureIcon = wrap(Thermometer, "TemperatureIcon");
export const TtsIcon = wrap(Volume2, "TtsIcon");


/* ----------------------------------------------------------------------- */
/* Brand wordmarks — static SVG assets in public/brand/ generated by          */
/* scripts/gen-logo-assets.py (Unbounded glyphs baked to paths at the         */
/* supplied design SVGs' coordinates; location accent + white "DB" as         */
/* literal hex fills). Served as plain <img> so rendering never depends on   */
/* webfonts, CSS vars or currentColor — identical in dev, SSR and Docker.     */
/* ----------------------------------------------------------------------- */

export type MedbayLogoProps = Omit<ComponentProps<"img">, "src"> & {
  /** Rendered height in px (or any CSS length). */
  size?: number | string;
};

function LogoImg({ size = 16, src, style, ...p }: MedbayLogoProps & { src: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static brand asset
    <img
      src={src}
      alt="MEDBAY"
      style={{ height: size, width: "auto", display: "block", ...style }}
      {...p}
    />
  );
}

export function LogoStationIcon(props: MedbayLogoProps) {
  return <LogoImg src="/brand/medbay-station.svg" {...props} />;
}

export function LogoShipIcon(props: MedbayLogoProps) {
  return <LogoImg src="/brand/medbay-ship.svg" {...props} />;
}

export function LogoGroundIcon(props: MedbayLogoProps) {
  return <LogoImg src="/brand/medbay-ground.svg" {...props} />;
}
